import sys, json, math, copy
from pathlib import Path
import numpy as np
root=Path("D:/Code/ldiar")
sys.path.insert(0,str(root/"src/human_fall_detection"))
from core.nominal_leveling import (apply_nominal, build_nominal_model,
    inverse_nominal, validate_nominal_model)
from core.calibration import (validate_known_transform, validate_geometry_calibration,
    resolve_reference_transform, apply_transform, make_transform)

R=[]
def rec(name,ok,extra=""):
    R.append((name,bool(ok),extra))
    print(("PASS" if ok else "FAIL"),name,extra)

m=build_nominal_model(26.0,1.1,"innolidar")
# rotation properties
rot=np.asarray(m["rotation"])
rec("R_orthonormal", np.allclose(rot@rot.T,np.eye(3),atol=1e-12))
rec("R_det_plus1", abs(np.linalg.det(rot)-1)<1e-12)
rec("t_is_00h", m["translation_m"]==[0.0,0.0,1.1])
rec("kind_status", m["kind"]=="nominal_installation_leveling" and m["status"]=="nominal")
rec("flags_false", m["physical_verified"] is False and m["extrinsics_verified"] is False and m["runtime_eligible"] is False)
rec("frame_to", m["to_frame"]=="ground_nominal")
rec("units", m["units"]=={"length":"m","angle":"deg"})

# tamper fields not covered by author tests
tamper={"provenance":"measured","up_source":[0,0,1],"extrinsics_verified":True,
        "model_id":"nominal:deadbeef","from_frame":"other","to_frame":"x",
        "convention":"x","schema":1.0,"schema":True,"extra":1}
for k,v in tamper.items():
    mm=copy.deepcopy(m); mm[k]=v
    try:
        validate_nominal_model(mm); rec("tamper_"+k, False, "accepted")
    except (ValueError,TypeError,OverflowError) as e:
        rec("tamper_"+k, True, type(e).__name__)
mm=copy.deepcopy(m); del mm["height_m"]
try:
    validate_nominal_model(mm); rec("missing_height",False)
except (ValueError,TypeError,KeyError) as e:
    rec("missing_height",True,type(e).__name__)

# numpy / bool / string types
rec("np_scalars_ok", build_nominal_model(np.float64(26),np.int64(1),"innolidar")["height_m"]==1.0)
for bad in [np.bool_(True), True, "26", [26], np.array([26.0])]:
    try:
        build_nominal_model(bad,1.1,"innolidar"); rec("bad_pitch_%r"%type(bad).__name__,False)
    except (ValueError,TypeError) as e:
        rec("bad_pitch_%r"%type(bad).__name__,True,type(e).__name__)
for bad in [float("nan"),float("inf"),-1,1e9]:
    try:
        build_nominal_model(26,bad,"innolidar"); rec("bad_height_%s"%bad,False)
    except ValueError as e:
        rec("bad_height_%s"%bad,True)
for pitch in [-90,-10,0,26,40,90]:
    try:
        build_nominal_model(pitch,1.1,"innolidar"); rec("pitch_ok_%s"%pitch,True)
    except Exception as e:
        rec("pitch_ok_%s"%pitch,False,repr(e))
