for fr,to in [("a","a"),("","b"),("  ","b"),(1,"b"),("a","")]:
    try:
        build_nominal_model(26,1.1,fr,to); rec("frame_bad_%r_%r"%(fr,to),False)
    except (ValueError,TypeError) as e:
        rec("frame_bad_%r_%r"%(fr,to),True)

# content id changes on frames too
rec("id_frame_change", build_nominal_model(26,1.1,"innolidar","ground_nominal")["model_id"]
    != build_nominal_model(26,1.1,"innolidar2")["model_id"])

