     [math.sin(math.radians(26))*2,1,math.cos(math.radians(26))*2+1.1]]))
for pts in [ [[1,True,0]], [["1",0,0]], [[float("nan"),0,0]], [[1,2]] ]:
    try:
        apply_nominal(pts,m,"innolidar"); rec("apply_bad_%r"%pts,False)
    except (ValueError,TypeError) as e:
        rec("apply_bad_%r"%pts,True)
